import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-native-slice-website',site=stage+'/website',parentFile='F:/VisibleMedicine/staging/20261024-regional-discovery-ui/SOURCE_BOUND.json',proposalFile='F:/VisibleMedicine/staging/20261024-native-slice-commit/PROPOSAL_BOUND.json';
assert.equal(hash(parentFile),'a58bdf58304bfc74e16639ea8708463c6cdde9d94b99d73214ced179b613f958');assert.equal(hash(proposalFile),'9bed26d92efacf0f4bc6862943cf6953bab1e30cd6474647e5fddd07ea10bd80');
const parent=json(parentFile),proposal=json(proposalFile),p=json('CURRENT_CHECKPOINT.json');assert.equal(p.goal.status,'active');assert.equal(p.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert.equal(p.activeWork.current.activeExecutionSessions.length,0);
const git=(...a)=>execFileSync('git',a,{encoding:'utf8',windowsHide:true,stdio:'pipe'}).trim();assert.equal(git('-C','F:/VisibleMedicine/website','rev-parse','HEAD'),'b953ff3f5f1891599cb6e91cb91311d9d6006270');assert.equal(git('-C',parent.atlas,'rev-parse','HEAD'),parent.atlasHead);assert.equal(git('-C',parent.atlas,'status','--porcelain'),'');
assert(!fs.existsSync(stage));fs.mkdirSync(stage);git('clone','--shared','--no-checkout','F:/VisibleMedicine/website',site);git('-C',site,'read-tree','HEAD');
const copy=(from,to)=>{fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(from,to,fs.constants.COPYFILE_EXCL);};
for(const r of parent.sourceRows){assert.equal(hash(parent.website+'/'+r.path),r.sha256,r.path);const to=path.resolve(site,r.path);assert(to.startsWith(path.resolve(site)+path.sep));copy(parent.website+'/'+r.path,to);}
const changes=[...proposal.changedAuthoredPaths,...proposal.newPaths];for(const name of changes){const row=proposal.sourceRows.find(r=>r.path===name);assert(row);assert.equal(hash(proposal.website+'/'+name),row.sha256);if(fs.existsSync(site+'/'+name))copy(site+'/'+name,stage+'/preimages/'+name+'.raw');fs.copyFileSync(proposal.website+'/'+name,site+'/'+name);}
for(const p of ['HeadAtlasViewer.tsx',...proposal.changedAuthoredPaths.filter(p=>p.startsWith('tests/'))])copy(path.dirname(proposalFile)+'/before/'+p,stage+'/before/'+p);
for(const file of ['tests/fixtures/current-atlas-delivery.json','tests/adjacent-current-tour-source-role.mjs','tests/regional-discovery-source-contract.test.mjs'])copy(site+'/'+file,stage+'/preimages/'+file+'.raw');
fs.symlinkSync(parent.website+'/node_modules',site+'/node_modules','junction');fs.symlinkSync(parent.atlas,stage+'/atlas','junction');
const route=parent.website+'/.next/types/routes.d.ts';assert(fs.existsSync(route));copy(route,site+'/.next/types/routes.d.ts');
const write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'});write(stage+'/PREPARATION.json',{at:new Date().toISOString(),website:site,parentReceipt:parentFile,parentReceiptSha256:hash(parentFile),parentWebsite:parent.website,proposalReceipt:proposalFile,proposalReceiptSha256:hash(proposalFile),atlas:parent.atlas,atlasHead:parent.atlasHead,atlasTree:parent.atlasTree,baseSourcePaths:parent.sourceRows.length,changedAuthoredPaths:proposal.changedAuthoredPaths,newPaths:proposal.newPaths,actualRouteTypes:{from:route,sha256:hash(route),notAShim:true},privateModulesRemainLocal:true,previewChanged:false,installed:false});
console.log(JSON.stringify({stage,sourceInputs:parent.sourceRows.length,proposalPaths:changes.length,previewChanged:false}));
